package com.khanh.fooddelivery.delivery_service.client;
import java.util.*; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpHeaders;
@FeignClient(name="driver-service") public interface DriverServiceClient { @GetMapping("/internal/v1/drivers/available") List<UUID> available(@RequestHeader(HttpHeaders.AUTHORIZATION) String authorization); @PostMapping("/internal/v1/drivers/{driverId}/reserve/{deliveryId}") void reserve(@RequestHeader(HttpHeaders.AUTHORIZATION) String authorization,@PathVariable UUID driverId,@PathVariable UUID deliveryId); @PostMapping("/internal/v1/drivers/{driverId}/release/{deliveryId}") void release(@RequestHeader(HttpHeaders.AUTHORIZATION) String authorization,@PathVariable UUID driverId,@PathVariable UUID deliveryId); }
